"""One-time final-study promotion helper; maintain the finished index.html directly."""
from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[1]
path=ROOT/'docs/index.html'
s=path.read_text(encoding='utf-8')
if 'id="prediction-form"' in s:
    raise SystemExit('Final website content already installed; edit index.html directly.')

for before,after in {
    '20K DEVELOPMENT STUDY':'FINAL 10K STUDY', '20,000-ROW DEVELOPMENT DATASET':'FINAL 10,000-ROW DATASET',
    '20,000-row study':'10,000-row final study','20,000-row development study':'10,000-row final study',
    '20,000':'10,000','20,142':'10,083','2,029':'1,027','142 rejected and replaced':'83 rejected and replaced',
    '15,000':'7,000','2,500':'1,500','97.92%':'93.73%','2,448':'1,406','+4.28%':'+5.77%',
    'on the 15,000':'on the 7,000','this run restored epoch 413 after stopping at 463':'the final run used the 500-epoch budget and restored its best validation-loss checkpoint',
    'on 128 stored plants':'on 32 stratified spot-check plants','1.78 × 10⁻¹⁵':'4.44 × 10⁻¹⁶',
    'pid_dataset_20000.csv':'pid_dataset_final_10000.csv','seed 20261117':'seed 8675309',
    '0bd540d44914e6dfcb76179688639203004f0a6ec3ac161ea7ca4c399dae2ba0':'e86f0039c0747afa186a322bdc89f77b99f03a1ba9aaa77a40c6243e64d97089',
    'No final-10K model results are presented here.':'The final test set was scored once after settings were locked.'
}.items(): s=s.replace(before,after)
s=re.sub(r'<div class="study-note"><span class="note-dot"></span><div><strong>Development evidence.*?</div></div>',
    '<div class="study-note"><span class="note-dot"></span><div><strong>Final study: 10,000 accepted plants.</strong> 7,000 training / 1,500 validation / 1,500 test. Settings and model weights were locked before test scoring. Learning curves, timing and rejected-plant stress tests are separate, clearly labeled analyses.</div></div>',s,flags=re.S)

bounds='''<div class="research-section" id="sampling-bounds"><p class="eyebrow">SCOPE / THE BOUNDS</p><h2>Exactly which plants and gains are allowed?</h2><div class="study-table-wrap"><table class="study-table"><thead><tr><th>Quantity</th><th>Range</th><th>How it is used</th></tr></thead><tbody><tr><td>K</td><td>0.5 ≤ K ≤ 2</td><td>Uniform plant-gain draw</td></tr><tr><td>ωₙ</td><td>0.5 ≤ ωₙ ≤ 10 rad/s</td><td>Uniform natural-frequency draw</td></tr><tr><td>ζ</td><td>0.1 ≤ ζ ≤ 2</td><td>Uniform damping draw</td></tr><tr><td>τ</td><td>0 ≤ τ ≤ 1 s</td><td>Exactly zero with probability 10%; otherwise continuous uniform positive delay</td></tr><tr><td>Kp, Ki</td><td>0.001 ≤ Kp, Ki ≤ 100</td><td>Numerical-search and validation bounds</td></tr><tr><td>Kd</td><td>0 ≤ Kd ≤ 50</td><td>Numerical-search and validation bound</td></tr></tbody></table></div><p>The plant draws are independent. Browser controls round to 0.01; the Python dataset uses continuous draws. No final reference controller hits an upper gain bound. These bounds define the studied population, not every possible second-order plant.</p></div>
<div class="research-section" id="generation-rejections"><p class="eyebrow">QUALITY / WHY SOME ROWS ARE REJECTED</p><h2>A plant needs a trustworthy label.</h2><p>We attempted <strong>10,083 plants</strong> to obtain exactly <strong>10,000 accepted rows</strong>. A plant is rejected only when no candidate search returns an independently accepted controller. The sampled open-loop plant is stable; the candidate closed-loop controller may not be.</p><div class="study-table-wrap"><table class="study-table"><thead><tr><th>Reason</th><th>What it means</th></tr></thead><tbody><tr><td>No feasible start / solver failure</td><td>Screening finds no usable starting controller, or the local optimizer does not converge successfully.</td></tr><tr><td>Invalid gains or unstable loop</td><td>Candidate gains are nonfinite/out of bounds, or closed-loop poles fail the stability check.</td></tr><tr><td>Overshoot</td><td>Refined peak output exceeds the unit-setpoint 10% limit.</td></tr><tr><td>Settling or duration limit</td><td>The response does not reach the required tail tolerance within the 1,000 s horizon cap.</td></tr><tr><td>Resolution limit</td><td>ITAE or peak checks cannot converge before the 65,537-point grid cap. Small positive delays can create very fast Padé modes.</td></tr></tbody></table></div><p>Rejected attempts are logged and replaced by new plants. This introduces selection bias toward plants our labeling pipeline can handle. <strong>Rejection is not proof that PID control is impossible.</strong> In Results & Evidence, we test the frozen models on the 83 rejected plants, distinguishing strict validation from an expanded numerical grid budget.</p></div>'''
needle='<ol class="pipeline generation-stages"'
s=s.replace(needle,bounds+'\n        '+needle,1)

start=s.index('<div class="equation-block">qₚ')
end=s.index('</div><aside class="editorial-aside">',start)
s=s[:start]+'''<div class="math-block"><div>q<sub>p</sub> = y<sub>ss</sub> K<sub>p</sub></div><div>q<sub>i</sub> = y<sub>ss</sub> t<sub>rise</sub> K<sub>i</sub></div><div>q<sub>d</sub> = <span class="fraction"><span>y<sub>ss</sub> K<sub>d</sub></span><span>t<sub>rise</sub></span></span></div></div><p>Decode the prediction before evaluating the controller:</p><div class="math-block math-row"><span>K<sub>p</sub> = <span class="fraction"><span>q<sub>p</sub></span><span>y<sub>ss</sub></span></span></span><span>K<sub>i</sub> = <span class="fraction"><span>q<sub>i</sub></span><span>y<sub>ss</sub> t<sub>rise</sub></span></span></span><span>K<sub>d</sub> = <span class="fraction"><span>q<sub>d</sub> t<sub>rise</sub></span><span>y<sub>ss</sub></span></span></span></div>'''+s[end:]

live='''<div class="research-section"><p class="eyebrow">03 / TRY THE FROZEN MODEL</p><h2>Bring a row. Predict a controller.</h2><p>Use the final 7K-trained MLP. Supply five measured features, or give a physical plant so the simulator can derive the same features. Predictions run locally from frozen weights; this does not retrain the model or alter the reported test statistics.</p><div class="research-panel prediction-panel"><div class="research-panel-header"><h3>A live prediction, not a saved curve.</h3><span class="micro-label">FINAL 10K MLP</span></div><div class="research-panel-body"><form id="prediction-form"><div class="chart-controls"><label for="prediction-mode">INPUT <select id="prediction-mode"><option value="features">Measured response features</option><option value="plant">Physical plant parameters</option></select></label><label for="prediction-example">START FROM <select id="prediction-example"><option value="">Enter my own values</option></select></label></div><div id="prediction-feature-fields" class="prediction-fields"><label>Rise time t<sub>rise</sub> <span>s</span><input name="t_rise" type="number" step="any" min="0.000001" required></label><label>Settling time t<sub>settling</sub> <span>s</span><input name="t_settling" type="number" step="any" min="0" required></label><label>Peak output y<sub>peak</sub><input name="y_peak" type="number" step="any" min="0.000001" required></label><label>Final output y<sub>ss</sub><input name="y_ss" type="number" step="any" min="0.000001" required></label><label>Onset estimate τ<sub>est</sub> <span>s</span><input name="tau_est" type="number" step="any" min="0" required></label></div><label class="check-control" id="prediction-known-label"><input id="prediction-known" type="checkbox"> I also know the plant and want to verify the response</label><div id="prediction-plant-fields" class="prediction-fields" hidden><label>Plant gain K <span>0.5–2</span><input name="K" type="number" step="any" min="0.5" max="2"></label><label>Natural frequency ω<sub>n</sub> <span>0.5–10 rad/s</span><input name="wn" type="number" step="any" min="0.5" max="10"></label><label>Damping ratio ζ <span>0.1–2</span><input name="zeta" type="number" step="any" min="0.1" max="2"></label><label>Dead time τ <span>0–1 s</span><input name="tau" type="number" step="any" min="0" max="1"></label></div><label class="check-control" id="prediction-compare-label" hidden><input id="prediction-compare" type="checkbox"> Compare with a fresh four-start numerical optimization</label><div class="hero-actions"><button class="primary-button" id="prediction-run" type="submit">Predict PID gains →</button><button id="prediction-cancel" type="button" hidden>Cancel</button></div></form><p id="prediction-status" class="prediction-status" role="status">Choose an example or enter a measured row.</p><div id="prediction-gains" class="readout-grid" aria-live="polite"></div><div id="prediction-features-note" class="chart-caption"></div><div id="prediction-response" hidden><svg id="prediction-chart" class="research-chart" viewBox="0 0 800 380" role="img" aria-label="Live predicted-controller response"></svg><div class="chart-legend"><span><i class="red"></i> Predicted PID</span><span><i></i> Numerical PID, if requested</span><span><i class="grey"></i> Open-loop plant</span><span><i class="dotted"></i> Setpoint = 1</span></div><div id="prediction-metrics"></div></div><p class="chart-caption">Feature-only inputs give a gain prediction, not a unique plant. Response plots, overshoot and ITAE require a known physical model. Verification uses ideal PID, second-order Padé delay and the same strict checks as the final evaluation. Predicted gains are not clipped and rejected/unresolved controllers are not counted as passes.</p><details class="evidence-details"><summary>Local computation and model export</summary><p>The browser MLP export was checked against 64 frozen validation examples. Physical simulations load NumPy/SciPy through Pyodide on first use and run in a worker. Inputs are not uploaded. Small browser/desktop rounding differences are possible; the current predicted gains are independently checked. Feature collection, runtime loading and verification are separate from inference latency.</p></details></div></div></div>'''
needle='<div class="research-section"><p class="eyebrow">03 / LOOK AT A RESPONSE'
s=s.replace(needle,live+'\n        '+needle,1).replace('03 / LOOK AT A RESPONSE','04 / SAVED TEST RESPONSES')
start=s.index('<div class="research-section"><p class="eyebrow">04 / DOES MORE DATA HELP?')
end=s.index('<div class="research-section"><p class="eyebrow">05 / ERROR ANALYSIS',start)
s=s[:start]+'''<div class="research-section"><p class="eyebrow">05 / DATASET SIZE</p><h2>More data helps.<br>The return per plant gets smaller.</h2><svg id="learning-chart" class="research-chart" viewBox="0 0 800 380" role="img" aria-label="Common-validation learning curves up to 20000 training plants"></svg><div id="learning-legend" class="chart-legend"></div><p id="learning-note" class="chart-caption"></p><p id="dataset-choice">Our final 10,000-row dataset supplies 7,000 training examples. The decision balances model performance, numerical labeling cost, reproducibility and a manageable undergraduate study. Larger datasets can still improve acceptance; 10K is not a proven optimum or a deployment safety threshold.</p><details class="evidence-details"><summary>How is this curve a fair comparison?</summary><p>Every point uses the same 500 final-validation plants and fixed model settings. Training prefixes are nested: the original final-training rows, then independent plants from the earlier development cohort. MLP stopping uses the same full validation partition. The final test set is never used or rescored for these curves. The axis counts <strong>training plants</strong>, not total dataset rows: the final 10K dataset corresponds to the 7K marker. This single-seed diagnostic is not a confidence interval.</p></details></div>'''+s[end:]
s=s.replace('05 / ERROR ANALYSIS','06 / ERROR ANALYSIS').replace('Fifty-two MLP controllers do not pass.','Ninety-four MLP controllers exceed the overshoot limit.')
s=s.replace('yet only 1,406 pass the full acceptance criteria: 51 exceed the overshoot limit and one reaches the resolution cap. Of the 51 overshoot misses, 38 are between 10% and 12%, 10 between 12% and 15%, and 3 between 15% and 20%.','yet only 1,406 pass the full acceptance criteria. All 94 failures exceed 10% overshoot: 61 fall between 10–12%, 28 between 12–15%, 3 between 15–20%, and 2 exceed 20%. Maximum measured overshoot is 27.53%.')
s=s.replace('90th-percentile ITAE ratio is 1.495× and the maximum is 26.10×; 99 of the 1,406 accepted pairs exceed 2×','90th-percentile ITAE ratio is 1.600× and the maximum is 9.61×; 78 of the 1,406 accepted pairs exceed 2×')
s=re.sub(r'<aside class="editorial-aside"><h3>A separate, harder stress test\.</h3>.*?</aside>', '<aside class="editorial-aside"><h3>Some plant regions are harder.</h3><p>The final MLP passes all 154 zero-delay test plants. Acceptance is 91.07% for dead time above 0.5 s and 91.48% for damping below 0.5. These descriptive patterns were not used for post-test tuning.</p><p>The teacher supplies local reference gains. Small gain errors can move a controller across the overshoot boundary even when aggregate gain R² is high.</p></aside>',s,flags=re.S)
needle='<div class="research-section"><p class="eyebrow">06 / COMPUTATION'
stress='''<div class="research-section"><p class="eyebrow">07 / REJECTED-PLANT STRESS TEST</p><h2>A missing label is not an impossible plant.</h2><p>We recovered the 83 plants rejected during final-data generation. Frozen final models predict gains from measured features without optimization or retraining. This deliberately difficult stress set is separate from the 1,500-plant test set.</p><div id="stress-table"></div><p id="stress-note"></p><p class="chart-caption">The strict cap is 65,537 points. Only resolution-limit outcomes are retried with up to 262,145 points; gains, tolerances, overshoot limit and horizon cap do not change. Expanded-budget results are not standard-budget passes. There are no accepted teacher labels for these plants, so target-gain error and reference-relative ITAE cannot be computed.</p></div>'''
s=s.replace(needle,stress+needle,1).replace('06 / COMPUTATION','08 / COMPUTATION')
start=s.index('<div class="research-section"><p class="eyebrow">08 / COMPUTATION')
end=s.index('</section>',start)
s=s[:start]+'''<div class="research-section"><p class="eyebrow">08 / WHY USE ML?</p><h2>Amortize the search.<br>Keep the verification.</h2><div class="research-two"><div><h3>The edge is repeated, cheap inference.</h3><p>A numerical optimizer needs a plant model and repeatedly simulates candidate gains. After offline training, our MLP predicts from five empirical features in one forward pass, avoiding explicit physical-parameter identification at inference. The labeling/search cost is paid upfront and amortized over many future predictions.</p><p>This is a useful shortcut within the learned family. Numerical optimization remains useful when a plant model is known, requirements change or a new reference controller is needed.</p></div><aside class="editorial-aside"><h3>Speed is not a safety certificate.</h3><p>ML occasionally misses the overshoot limit. A step response still has to be recorded; feature collection can dominate inference time. Independent verification adds cost and is harder on an unknown real plant than on a known synthetic model.</p></aside></div><svg id="speed-chart" class="research-chart" viewBox="0 0 800 320" role="img" aria-label="Model and optimizer timings"></svg><p id="speed-note" class="chart-caption"></p><p class="chart-caption">Warm CPU timings on 20 validation plants; prediction excludes feature collection, loading and training. Verified-workflow speedups use jointly accepted cases. Timing is machine-specific and is not a new accuracy estimate.</p></div>'''+s[end:]

# Finalize future-work language without changing the established limits.
start=s.index('<div class="research-section"><p class="eyebrow">NEXT / FINISH THE STUDY')
end=s.index('<div class="research-section"><p class="eyebrow">REPRODUCIBILITY',start)
s=s[:start]+'''<div class="research-section"><p class="eyebrow">NEXT / BEYOND THIS STUDY</p><h2>Test robustness before deployment.</h2><div class="decision-track"><article><h3>Realistic measurements and actuators.</h3><p>Study noise, finite sampling, derivative filtering, actuator saturation and disturbance rejection.</p></article><article><h3>Independent delay and uncertainty checks.</h3><p>Verify against true delay, parameter drift and stability margins, beyond the Padé model used by the teacher.</p></article><article><h3>Keep future improvements separate.</h3><p>The current test results have been observed. Further model development needs training/validation data and a fresh untouched assessment for a new claimed improvement.</p></article></div></div>'''+s[end:]
s=s.replace('The fresh 10K dataset can support a clearly separated final study, provided its test set remains untouched until settings are locked.','The final settings were locked before test scoring. The extended size study uses validation only and does not alter the frozen final models.')
s=s.replace('the development dataset hash','the final dataset hash').replace('from saved prediction and experiment artifacts, not live retraining in the browser','from saved final-study artifacts. Live demo results are newly computed and are not mixed into test statistics')
s=s.replace('their final presentation will be organized separately','their implementation and audit trail can be checked there')
s=s.replace('The full repository is linked for implementation details; its final presentation will be organized separately.','The repository links to implementation details, model artifacts and evaluation scripts.')

# Format scientific symbols in visible HTML text, never in identifiers or attributes.
symbols={'y_ss':'y<sub>ss</sub>','t_rise':'t<sub>rise</sub>','t_settling':'t<sub>settling</sub>',
 'y_peak':'y<sub>peak</sub>','tau_est':'τ<sub>est</sub>','Kp':'K<sub>p</sub>','Ki':'K<sub>i</sub>','Kd':'K<sub>d</sub>',
 'q_d':'q<sub>d</sub>','qₚ':'q<sub>p</sub>','qᵢ':'q<sub>i</sub>','ωₙ':'ω<sub>n</sub>','²':'<sup>2</sup>'}
pieces=re.split(r'(<[^>]+>)',s)
for i in range(0,len(pieces),2):
    for plain,pretty in symbols.items(): pieces[i]=pieces[i].replace(plain,pretty)
s=''.join(pieces)
s=s.replace('<div class="equation-block">','<div class="equation-block math-block">')
s=s.replace('<script src="research.js" defer></script>','<script src="research.js" defer></script>\n  <script src="model-data.js" defer></script>\n  <script src="model-inference.js" defer></script>\n  <script src="prediction-worker.js" defer></script>\n  <script src="prediction.js" defer></script>')
s=s.replace('<link rel="stylesheet" href="theme.css">','<link rel="stylesheet" href="theme.css">\n  <link rel="stylesheet" href="prediction.css">')
path.write_text(s,encoding='utf-8')
print('Installed final narrative, bounds, rejection reasons, notation and live explorer markup.')
